{"additionalProperties":false,"properties":{"assessments":{"items":{"additionalProperties":false,"properties":{"instance_verdicts":{"items":{"additionalProperties":false,"properties":{"memory_version":{"additionalProperties":false,"properties":{"memory_id":{"maxLength":256,"minLength":1,"type":"string"},"revision":{"minimum":1,"type":"integer"}},"required":["memory_id","revision"],"type":"object"},"verdict":{"enum":["supports","contradicts","unknown"]}},"required":["memory_version","verdict"],"type":"object"},"maxItems":8,"minItems":2,"type":"array"},"link_verdict":{"enum":["supports","contradicts","unknown",null]},"proposal_id":{"maxLength":256,"minLength":1,"type":"string"},"proposal_verdict":{"enum":["supports","contradicts","unknown"]},"relations":{"items":{"additionalProperties":false,"properties":{"evidence_index":{"minimum":0,"type":"integer"},"verdict":{"enum":["supports","contradicts","unknown","irrelevant"]}},"required":["evidence_index","verdict"],"type":"object"},"maxItems":32,"minItems":1,"type":"array"},"request_verdict":{"enum":["supports","contradicts","unknown"]},"supporting_evidence_indices":{"items":{"minimum":0,"type":"integer"},"maxItems":32,"minItems":0,"type":"array"}},"required":["proposal_id","proposal_verdict","link_verdict","relations"],"type":"object"},"maxItems":72,"minItems":0,"type":"array"}},"required":["assessments"],"type":"object"}
